  x.fillStyle='#1c150d';const by=h*.66;for(let px=0;px<w;){const bw=30+R()*90,bh=40+R()*h*.28;x.fillRect(px,by-bh,bw,bh+h);if(R()<.5){x.fillStyle='#2a2014';for(let k=0;k<5;k++)x.fillRect(px+R()*bw,by-bh+R()*bh,8,12);x.fillStyle='#1c150d'}px+=bw+R()*6}
