  x.fillStyle='#0e0a06';x.fillRect(0,h*.78,w,h*.22);const tx_=w*.58,ty=h*.8;x.beginPath();x.moveTo(tx_-120,ty);x.lineTo(tx_+110,ty);x.lineTo(tx_+95,ty-40);x.lineTo(tx_-100,ty-40);x.fill();x.fillRect(tx_-50,ty-70,90,32);x.fillRect(tx_+38,ty-60,120,8);
  for(let i=0;i<5;i++){const sx=w*.3+i*46,sy=h*.84;x.fillRect(sx,sy-48,12,30);x.beginPath();x.arc(sx+6,sy-54,8,0,6.28);x.fill();x.fillRect(sx+2,sy-18,4,20);x.fillRect(sx+7,sy-18,4,20);x.save();x.translate(sx+10,sy-40);x.rotate(-.5-i*.05);x.fillRect(0,0,34,3);x.restore()}
